const $=s=>document.querySelector(s), reduced=matchMedia('(prefers-reduced-motion: reduce)');
const NAV=[['overview','Overview','overview'],['handoffs','Handoffs','handoffs'],['activities','Activity register','activities'],['pain','Pain points','pain'],['tpis','Process improvements','tpis'],['controls','Controls & KPIs','controls'],['ai','AI suggestions','ai'],['notes','Source notes','notes']];
const paths={plus:'M12 5v14M5 12h14',minus:'M5 12h14',expand:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',collapse:'M3 8h5V3m8 0v5h5M8 21v-5H3m13 5v-5h5',back:'m15 18-6-6 6-6M9 12h12',close:'m6 6 12 12M6 18 18 6',arrow:'M5 12h14m-5-5 5 5-5 5',search:'M21 21l-5-5m2-6a7 7 0 1 1-14 0 7 7 0 0 1 14 0',overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',handoffs:'M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4',activities:'M9 5h12M9 12h12M9 19h12M3 5h1M3 12h1M3 19h1',pain:'M12 3 2 21h20L12 3Zm0 6v5m0 3v1',tpis:'M4 20V9m8 11V4m8 16v-7M2 20h20',controls:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Zm-4 9 3 3 5-6',ai:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',notes:'M5 3h10l4 4v14H5V3Zm10 0v5h4M8 12h8M8 16h8',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.notes}"/></svg>`;
const names={man:'Manual',hyb:'Semi',auto:'Automated'};
const tag=(text,kind='')=>`<span class="tw-tag ${kind}">${esc(text)}</span>`;
const textValue=v=>v===true?'Yes':v===false?'No':Array.isArray(v)?v.map(textValue).join(' · '):v&&typeof v==='object'?Object.entries(v).map(([k,v])=>`${k}: ${textValue(v)}`).join(' · '):String(v??'');
const field=(label,value)=>value!==undefined&&value!==null&&textValue(value)!==''?`<div><dt>${esc(label)}</dt><dd>${esc(textValue(value))}</dd></div>`:'';
const titleClean=s=>s.replace(/\s+\d+\s*$/,'');
let entryContext=null;
let activeId=null,view='handoffs',opener=null,neural=null,openMap,token=0,drawerOpener=null,activityType='',fullscreenPlaceholder=null;
const motion=()=>!reduced.matches&&!document.body.classList.contains('keyboard-input');
export function configureDashboard(options){openMap=options.openMap;}
export function destroyDashboard(){setHandoffFullscreen(false,false);neural?.destroy();neural=null;}
function setHandoffFullscreen(expanded,focus=true){
 const modal=$('#tower-workbench'),panel=$('#tw-network-panel');
 if(!modal||!panel||expanded===Boolean(fullscreenPlaceholder))return;
 const toggle=$('#tw-fullscreen');
 if(expanded){
  fullscreenPlaceholder=document.createComment('Handoff network position');
  panel.before(fullscreenPlaceholder);modal.append(panel);
 }else{
  fullscreenPlaceholder.replaceWith(panel);fullscreenPlaceholder=null;
 }
 modal.classList.toggle('is-handoff-fullscreen',expanded);
 modal.querySelector('.tw-main').inert=expanded;modal.querySelector('.tw-rail').inert=expanded;
 panel.classList.toggle('is-fullscreen',expanded);
 toggle.setAttribute('aria-expanded',String(expanded));
 toggle.innerHTML=icon(expanded?'collapse':'expand')+(expanded?'Exit Fullscreen':'View Fullscreen');
 requestAnimationFrame(()=>neural?.fitToView());
 if(focus)toggle.focus({preventScroll:true});
}
const content=loadSourceRegisters;
function animateNumbers(root){if(!motion())return;const nodes=[...root.querySelectorAll('[data-total]')],start=performance.now();function step(now){if(!root.isConnected)return;const n=Math.min((now-start)/550,1);nodes.forEach(el=>el.textContent=Math.round(+el.dataset.total*(1-(1-n)**3)));if(n<1)requestAnimationFrame(step)}requestAnimationFrame(step)}
function shell(t){return `<aside class="tw-rail"><button class="tw-back" id="tw-close">${icon('back')}<span>Back to organ</span></button><div class="tw-identity"><span class="tw-monogram">${esc(t.sourceKey)}</span><h2 id="tw-tower-title">${esc(t.name)}</h2><p>Finance process review</p></div><nav class="tw-navigation" aria-label="Tower contents">${NAV.map(([id,label,ico])=>`<button data-nav="${id}">${icon(ico)}<span>${label}</span>${['pain','tpis'].includes(id)?`<small>${t.counts[id]}</small>`:''}</button>`).join('')}</nav></aside><main class="tw-main"><div class="tw-topline"><span>${esc(t.name)}</span>${scenarioControl(getScenario(activeId),'Insights scenario')}</div><div class="tw-mobile-nav"><label for="tw-mobile-section">Contents</label><select id="tw-mobile-section">${NAV.map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select></div><div class="tw-scroll" id="tw-scroll"><div id="tw-page" aria-live="polite"></div></div></main><div class="tw-drawer-backdrop" id="tw-drawer-backdrop" hidden></div><aside class="tw-drawer" id="tw-drawer" hidden role="dialog" aria-modal="true" aria-labelledby="tw-drawer-title"><div class="tw-drawer-top"><span>Record details</span><button id="tw-drawer-close" aria-label="Close record details">${icon('close')}</button></div><div id="tw-drawer-body"></div></aside>`;}
function pageHeader(title,description,actions=''){return `<header class="tw-page-heading"><div><h1 tabindex="-1" id="tw-page-title">${title}</h1><p>${description}</p></div>${actions?`<div class="tw-heading-actions">${actions}</div>`:''}</header>`;}
const button=(label,attrs='',primary=false,ico='arrow')=>`<button class="tw-button${primary?' tw-primary':''}" ${attrs}>${label}${icon(ico)}</button>`;
const empty=message=>`<div class="tw-empty">${message}</div>`;
const search=(id,placeholder='Search this register…')=>`<label class="tw-search">${icon('search')}<span class="tw-sr">${placeholder}</span><input type="search" id="${id}" placeholder="${placeholder}" autocomplete="off"></label>`;
function sourceBlock(s){return `<article class="tw-source" data-source-section="${esc(s.id)}">${s.html}</article>`;}
function showDrawer(title,body){drawerOpener=document.activeElement;$('#tw-drawer-title')?.remove();$('#tw-drawer-body').innerHTML=`<h2 id="tw-drawer-title">${esc(title)}</h2>${body}`;$('#tw-drawer').hidden=false;$('#tw-drawer-backdrop').hidden=false;$('#tower-workbench .tw-main').inert=true;$('#tower-workbench .tw-rail').inert=true;if(fullscreenPlaceholder)$('#tw-network-panel').inert=true;$('#tw-drawer-close').focus({preventScroll:true});if(motion())$('#tw-drawer').animate([{transform:'translateX(24px)',opacity:.7},{transform:'none',opacity:1}],{duration:220,easing:'cubic-bezier(.32,.72,0,1)'});}
function closeDrawer(){if($('#tw-drawer').hidden)return;$('#tw-drawer').hidden=true;$('#tw-drawer-backdrop').hidden=true;$('#tower-workbench .tw-main').inert=Boolean(fullscreenPlaceholder);$('#tower-workbench .tw-rail').inert=Boolean(fullscreenPlaceholder);$('#tw-network-panel')?.removeAttribute('inert');drawerOpener?.focus({preventScroll:true});}
function decorateSources(root){root.querySelectorAll('.tw-source').forEach(article=>{
 // The source supplies the content. Only reading controls and typography are rebuilt.
 article.querySelectorAll('table').forEach(table=>{if(!table.parentElement.classList.contains('tw-table-scroll')){const wrap=document.createElement('div');wrap.className='tw-table-scroll';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Source register; scroll horizontally for all columns');table.before(wrap);wrap.append(table)}
 const headers=[...table.querySelectorAll('thead th')].map(h=>h.textContent.trim());table.querySelectorAll('tbody tr').forEach((row,i)=>{const cells=[...row.cells];if(!headers.length)return;const control=document.createElement('button');control.className='tw-row-open';control.innerHTML=icon('arrow');control.setAttribute('aria-label',`Read full record ${i+1}`);const td=document.createElement('td');td.className='tw-detail-cell';td.append(control);row.append(td);const show=()=>showDrawer(cells.find(c=>c.textContent.trim().length>8)?.textContent.trim()||'Source record',`<dl class="tw-fields">${cells.map((cell,i)=>field(headers[i]||'Details',cell.textContent.trim())).join('')}</dl>`);control.onclick=show;row.addEventListener('click',e=>{if(!e.target.closest('a,button,summary'))show()})});if(headers.length){const th=document.createElement('th');th.innerHTML='<span class="tw-sr">Details</span>';table.querySelector('thead tr')?.append(th)}});
 article.querySelectorAll('a[href^="#"]').forEach(a=>{a.removeAttribute('href')});
 });}
function searchableSource(root,input){const articles=[...root.querySelectorAll('.tw-source')];input.oninput=()=>{const q=input.value.toLowerCase().trim();let matches=0;articles.forEach(article=>{const rows=[...article.querySelectorAll('tbody tr,.sc-opp')];if(!rows.length){article.hidden=q&&!article.textContent.toLowerCase().includes(q);if(!article.hidden)matches++;return}rows.forEach(row=>{row.hidden=!!q&&!row.textContent.toLowerCase().includes(q);if(!row.hidden)matches++});article.querySelectorAll('details').forEach(d=>{if(q)d.open=true});article.hidden=!!q&&!rows.some(r=>!r.hidden)});const msg=$('.tw-search-result');if(msg)msg.textContent=q?`${matches} matching records`:'All source records';let noResults=root.querySelector('.tw-source-empty');if(!noResults){noResults=document.createElement('div');noResults.className='tw-empty tw-source-empty';noResults.textContent='No source records match your search. Try a different term.';root.append(noResults)}noResults.hidden=!q||matches>0;};}
function overview(t,c){const n=t.counts,isAI=t.scenario==='tobe';return pageHeader('Tower overview',t.scope,button('High-level flow','data-map="high"',true,'map'))+`<div class="tw-overview-grid"><section class="tw-mix-panel"><div class="tw-section-title"><h2>${isAI?'Potential activity mix':'Current activity mix'}</h2>${tag(isAI?'If adopted':'As Is','current')}</div>${activityRing(n)}<div class="tw-mix-total"><strong data-total="${n.total}">${n.total}</strong><span>documented activities<br>across ${t.stages.length} stages</span></div><div class="tw-stack" role="img" aria-label="${n.auto} automated, ${n.semi} semi-automated, ${n.manual} manual">${[['auto',n.auto],['hyb',n.semi],['man',n.manual]].map(([k,v])=>`<i class="${k}" style="flex-grow:${v}"></i>`).join('')}</div><div class="tw-mix-labels">${[['auto',n.auto],['hyb',n.semi],['man',n.manual]].map(([k,v])=>`<button data-activity="${k}"><i class="tw-dot ${k}"></i><span>${names[k]}</span><b data-total="${v}">${v}</b></button>`).join('')}</div><p class="tw-note">${isAI?'Potential activity types if the source suggestions are adopted. Feasibility and LT comments remain in the AI registers.':'Activity types come from the As Is map. Proposed changes do not contribute to these counts.'}</p></section><section class="tw-context"><h2>Operating context</h2><dl class="tw-fields">${t.meta.map(([k,v])=>field(k,v)).join('')}</dl></section></div>${overviewVisuals(t)}<section class="tw-stages"><div class="tw-section-title"><h2>Stages at a glance</h2><span>${t.stages.length} stages · ${t.activities.length} activities</span></div>${t.stages.map((s,i)=>`<button class="tw-stage-row" data-stage="${esc(s.id)}"><span class="tw-stage-index">${String(i+1).padStart(2,'0')}</span><span class="tw-stage-copy"><strong>${esc(s.name.replace(/^Stage \d+:\s*/,''))}</strong><small>${esc(s.owner||'')}</small></span><span class="tw-stage-mix"><span class="tw-stack">${[['auto',s.counts.auto],['hyb',s.counts.hyb],['man',s.counts.man]].map(([k,v])=>`<i class="${k}" style="flex-grow:${v}"></i>`).join('')}</span><small>${s.counts.man} M · ${s.counts.hyb} S · ${s.counts.auto} A</small></span><span>${s.total}</span>${icon('arrow')}</button>`).join('')}</section><div class="tw-section-title"><h2>Process context from the source</h2></div>${c.asIs.filter(s=>isAI?s.id.startsWith('ba-'):s.id.startsWith('kp-')).map(sourceBlock).join('')}`;}
function handoffs(t){const isAI=t.scenario==='tobe',g=t.handoffGraph,ins=t.handoffs.filter(r=>r.direction==='in').length;return pageHeader('Handoffs & dependencies','Follow the work between teams. Select a flow to trace its incoming and outgoing connections.',button('Detailed flow','data-map="detail"',false,'map'))+`<div class="tw-facts"><span><strong data-total="${g.flows.length}">${g.flows.length}</strong> source flows</span><span><strong data-total="${ins}">${ins}</strong> inbound connections</span><span><strong data-total="${t.handoffs.length-ins}">${t.handoffs.length-ins}</strong> outbound connections</span><span>${tag('Documented As Is','current')}</span></div><div class="tw-network-toolbar"><div class="tw-segment" role="group" aria-label="Handoff view"><button data-handoff-view="network" aria-pressed="true">Neuron view</button><button data-handoff-view="register" aria-pressed="false">Connection register</button></div><label class="tw-select"><span class="tw-sr">Source flow</span><select id="tw-flow"><option value="">All source flows</option>${g.flows.map((f,i)=>`<option value="${i}">${esc(f.title)}</option>`).join('')}</select></label></div><p class="tw-swipe-hint">The network opens fitted to your screen. Zoom in to inspect a flow and its connections.</p><section class="tw-network" id="tw-network-panel"><div class="tw-network-top"><span><i class="tw-live-dot"></i>Handoff Network</span><div class="tw-network-actions"><div class="tw-zoom" role="group" aria-label="Network zoom"><button id="tw-zoom-out" aria-label="Zoom out" title="Zoom Out (−)">${icon('minus')}</button><output id="tw-zoom-value" aria-live="polite">100%</output><button id="tw-zoom-in" aria-label="Zoom in" title="Zoom In (+)">${icon('plus')}</button><button id="tw-zoom-fit" title="Fit Network (0)">Fit</button><button id="tw-zoom-reset" title="Actual Size">100%</button></div><button id="tw-flow-details" disabled>View details ${icon('arrow')}</button><button id="tw-fullscreen" aria-expanded="false" aria-controls="tw-network-panel">${icon('expand')}View Fullscreen</button></div></div><p class="tw-fullscreen-hint">Use the zoom controls to inspect the network.</p><div id="tw-neural"></div></section><section id="tw-connection-panel" hidden><div class="tw-register-tools">${search('tw-handoff-search','Search team, handoff or source…')}<span id="tw-handoff-count" role="status">${t.handoffs.length} records</span></div><div class="tw-table-scroll" tabindex="0" role="region" aria-label="Connection register"><table class="tw-table"><thead><tr><th>Source flow</th><th>Direction</th><th>Team / party</th><th>What moves</th><th>Source</th></tr></thead><tbody>${t.handoffs.map((r,i)=>`<tr data-flow="${esc(r.flowId)}" data-search="${esc(JSON.stringify(r).toLowerCase())}"><td><button class="tw-text-button" data-handoff-record="${i}">${esc(r.flow)}</button></td><td>${tag(r.direction==='in'?'Inbound':'Outbound',r.direction)}</td><td><strong>${esc(r.party)}</strong></td><td>${esc(r.detail)}</td><td>${esc(r.source||'Not specified in source')}</td></tr>`).join('')}</tbody></table></div><div class="tw-empty" id="tw-handoff-empty" hidden>No connections match your search. Try another team or reset the source flow.</div></section><p class="tw-note">Labels, source flows and connections match the original handoff diagram. A repeated connection is counted as it appears in the source.</p>${isAI?`<section class="tw-proposed-dependencies"><div class="tw-section-title"><h2>AI-suggested dependencies</h2><span>${t.proposedDependencies.length} source suggestions</span></div><p class="tw-note">The original AI page retains the documented handoffs. These additional dependencies are explicitly marked as suggestions in its process map.</p>${t.proposedDependencies.length?`<div class="tw-table-scroll" tabindex="0"><table class="tw-table"><thead><tr><th>Stage</th><th>Direction</th><th>Party</th><th>What moves</th><th>Source</th></tr></thead><tbody>${t.proposedDependencies.map(d=>`<tr><td>${esc(d.stage)}</td><td>${d.direction==='in'?'Upstream':'Downstream'}</td><td>${esc(d.p)}</td><td>${esc(d.w)}</td><td>${esc(d.src)}</td></tr>`).join('')}</tbody></table></div>`:empty('No additional dependencies are explicitly marked as AI suggestions in this source.')}</section>`:''}`;}
function wireHandoffs(t){let selected=null;const g=t.handoffGraph;const filter=()=>{const q=$('#tw-handoff-search').value.toLowerCase(),flow=selected===null?'':g.flows[selected].id;let n=0;$('#tw-connection-panel').querySelectorAll('tbody tr').forEach(r=>{r.hidden=!!((flow&&r.dataset.flow!==flow)||(q&&!r.dataset.search.includes(q)));if(!r.hidden)n++});$('#tw-handoff-count').textContent=n+' records';$('#tw-handoff-empty').hidden=n>0};
 const selection=i=>{selected=i;$('#tw-flow').value=i===null?'':i;$('#tw-flow-details').disabled=i===null;$('#tw-flow-details').setAttribute('aria-label',i===null?'View details':'View details for '+g.flows[i].title);filter()};
 neural=createHandoffNeural($('#tw-neural'),{name:t.name,...g,onSelect:selection,onZoom:value=>{
  $('#tw-zoom-value').textContent=Math.round(value*100)+'%';
  $('#tw-zoom-out').disabled=value<=.25;$('#tw-zoom-in').disabled=value>=2.5;
 }});neural.setActive(true);
 $('#tw-zoom-in').onclick=()=>neural.setZoom(neural.getZoom()*1.2);
 $('#tw-zoom-out').onclick=()=>neural.setZoom(neural.getZoom()/1.2);
 $('#tw-zoom-fit').onclick=()=>neural.fitToView();
 $('#tw-zoom-reset').onclick=()=>neural.setZoom(1);
 $('#tw-network-panel').addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||e.ctrlKey||e.metaKey||e.altKey)return;if(['+','=','-','0'].includes(e.key)){e.preventDefault();if(e.key==='0')neural.fitToView();else neural.setZoom(neural.getZoom()*(e.key==='-'?1/1.2:1.2));}});
 $('#tw-flow').onchange=e=>neural.selectFlow(e.target.value===''?null:+e.target.value,true);
 $('#tw-handoff-search').oninput=filter;
 $('#tw-flow-details').onclick=()=>{const f=g.flows[selected];showDrawer(f.title,`<div class="tw-drawer-facts">${tag(f.inCount+' inbound','in')}${tag(f.outCount+' outbound','out')}</div>${['in','out'].map(dir=>`<h3>${dir==='in'?'Hands in':'Receives'}</h3>${t.handoffs.filter(r=>r.flowId===f.id&&r.direction===dir).map(r=>`<section class="tw-handoff-detail"><h4>${esc(r.party)}</h4><p>${esc(r.detail)}</p><small>${esc(r.source||'Source not specified')}</small></section>`).join('')||'<p>No documented connections.</p>'}`).join('')}`)};
 $('#tw-fullscreen').onclick=()=>setHandoffFullscreen(!fullscreenPlaceholder);
 document.querySelectorAll('[data-handoff-view]').forEach(b=>b.onclick=()=>{const isNetwork=b.dataset.handoffView==='network';$('#tw-network-panel').hidden=!isNetwork;$('.tw-swipe-hint').hidden=!isNetwork;$('#tw-connection-panel').hidden=isNetwork;neural.setActive(isNetwork);document.querySelectorAll('[data-handoff-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});
 document.querySelectorAll('[data-handoff-record]').forEach(b=>b.onclick=()=>{const r=t.handoffs[+b.dataset.handoffRecord];showDrawer(r.party,`<dl class="tw-fields">${field('Source flow',r.flow)}${field('Direction',r.direction==='in'?'Hands in':'Receives')}${field('What moves',r.detail)}${field('Source',r.source)}</dl>`)});
}
function activities(t){const isAI=t.scenario==='tobe';return pageHeader('Activity register',isAI?'Source activities with their proposed types if adopted. Open a record for the recommendation, original type and feasibility.':'Every documented As Is activity, with its owner, systems, inputs, outputs and control evidence.')+`<div class="tw-register-tools">${search('tw-activity-search','Search activities, owners or systems…')}<label class="tw-select"><span class="tw-sr">Activity type</span><select id="tw-activity-type"><option value="">All activity types</option>${Object.entries(names).map(([k,v])=>`<option value="${k}" ${activityType===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="tw-select"><span class="tw-sr">Stage</span><select id="tw-activity-stage"><option value="">All stages</option>${t.stages.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label></div><p class="tw-result-count" id="tw-activity-count" role="status"></p><div class="tw-record-list">${t.activities.map((a,i)=>`<button class="tw-record-row" data-activity-record="${i}" data-type="${a.effectiveType||a.ty}" data-stage-id="${esc(a.stageId)}" data-search="${esc(JSON.stringify(a).toLowerCase())}"><span class="tw-record-order">${esc(a.n)}</span><span class="tw-record-copy"><strong>${esc(a.t)}</strong><small>${esc(a.processId+' · '+a.process)}</small></span>${tag(names[a.effectiveType||a.ty]||a.ty,a.effectiveType||a.ty)}<span class="tw-record-owner">${esc(a.o)}</span>${icon('arrow')}</button>`).join('')}</div><div class="tw-empty" id="tw-activity-empty" hidden>No activities match these filters.</div>`;}
function wireActivities(t){const filter=()=>{const q=$('#tw-activity-search').value.toLowerCase(),ty=$('#tw-activity-type').value,stage=$('#tw-activity-stage').value;let n=0;document.querySelectorAll('[data-activity-record]').forEach(b=>{b.hidden=!!((q&&!b.dataset.search.includes(q))||(ty&&b.dataset.type!==ty)||(stage&&b.dataset.stageId!==stage));if(!b.hidden)n++});$('#tw-activity-count').textContent=`${n} of ${t.activities.length} activities`;$('#tw-activity-empty').hidden=n>0};$('#tw-activity-search').oninput=filter;$('#tw-activity-type').onchange=filter;$('#tw-activity-stage').onchange=filter;filter();document.querySelectorAll('[data-activity-record]').forEach(b=>b.onclick=()=>{const a=t.activities[+b.dataset.activityRecord];showDrawer(a.t,`${tag(names[a.effectiveType||a.ty]||a.ty,a.effectiveType||a.ty)}<dl class="tw-fields">${[['Stage',a.stage],['Process',a.process+' · '+a.processId],['Step',a.n],['What happens',a.d],['As Is activity type',names[a.asIsType]],['Activity type if adopted',names[a.effectiveType]],['AI recommendation',a.rec||a.sug],['Tools',a.tools],['Proposal basis',a.opp],['Feasibility',a.feas],['Review comments',a.feasc],['Copilot / Microsoft AI option',a.cop],['Who',a.o],['System',a.sys],['Input from',a.in],['Output to',a.out],['Decision',a.dec],['Pain points',a.pp],['CI / TPI',a.ci],['Control',a.ctl],['Source',a.src]].map(([k,v])=>field(k,v)).join('')}</dl>${button('View this stage',`data-drawer-stage="${esc(a.stageId)}"`,true,'map')}`);$('#tw-drawer [data-drawer-stage]').onclick=e=>goMap('detail',e.currentTarget.dataset.drawerStage)});}
function tpis(t,c){return pageHeader(entryContext?.project||'Process improvements','Documented TPI register entries, including feasibility, implementation status and source comments.',entryContext?.project?button('All TPI entries','id="tw-all-tpis"'): '')+`<div class="tw-register-tools">${search('tw-tpi-search','Search opportunity, status or category…')}<span class="tw-result-count" id="tw-tpi-count" role="status">${t.tpis.length} register entries</span></div><div class="tw-record-list">${t.tpis.map((r,i)=>`<button class="tw-record-row tw-tpi-row" data-tpi="${i}" data-search="${esc(JSON.stringify(r).toLowerCase())}"><span class="tw-record-code">${esc(r.id)}</span><span class="tw-record-copy"><strong>${esc(r.t||r.name)}</strong><small>${esc(r.register||r.pj||r.cat||'')}</small></span><span class="tw-record-status">${esc(r.st||r.sr||'Not specified')}</span>${icon('arrow')}</button>`).join('')}</div><div class="tw-empty" id="tw-tpi-empty" hidden>No improvements match your search.</div><section class="tw-source-registers"><div class="tw-section-title"><h2>Related initiatives in the source</h2></div><p class="tw-note">The source tables retain their original grouping, cross-tower links and CI entries. They may refer to the same initiatives as the register above.</p>${c.ai.filter(s=>/TPI/i.test(s.title)).map(sourceBlock).join('')}</section>`;}
function wireTpis(t){$('#tw-tpi-search').oninput=e=>{let n=0;const q=e.target.value.toLowerCase();document.querySelectorAll('[data-tpi]').forEach(b=>{b.hidden=!b.dataset.search.includes(q)||(entryContext?.entries&&!entryContext.entries.includes(+b.dataset.tpi));if(!b.hidden)n++});$('#tw-tpi-count').textContent=n+' register entries';$('#tw-tpi-empty').hidden=n>0};$('#tw-tpi-search').dispatchEvent(new Event('input'));if($('#tw-all-tpis'))$('#tw-all-tpis').onclick=()=>{entryContext=null;render('tpis',true)};document.querySelectorAll('[data-tpi]').forEach(b=>b.onclick=()=>{const r=t.tpis[+b.dataset.tpi];showDrawer(r.t||r.name,`${tag(r.id)}<dl class="tw-fields">${[['Register',r.register||r.pj],['Practical action',r.act],['Category',r.cat],['Source status',r.st||r.sr],['Source',r.src],['Remarks / comments',r.rem],['Register basis',r.basis],['Automation',r.auto??r.au],['AI',r.ai],['Cross-tower collaboration',r.xc||r.xt],['Steps',r.steps]].map(([k,v])=>field(k,v)).join('')}</dl>`)});}
function controls(t,c){const evidence=t.activities.filter(a=>a.ctl);return pageHeader('Controls & KPIs','Documented review controls, activity-level evidence and the KPI definitions provided in the source.')+`<section class="tw-control-section"><h2>Review & control checkpoints</h2>${c.controls?.length?`<ul class="tw-control-list">${c.controls.map((v,i)=>`<li>${icon('controls')}<span>${esc(textValue(v))}</span></li>`).join('')}</ul>`:empty('No separate tower-level control register is provided in this source.')}</section><section class="tw-control-section"><h2>Controls recorded on activities</h2>${evidence.length?`<div class="tw-record-list">${evidence.map(a=>`<div class="tw-control-row"><strong>${esc(a.ctl)}</strong><span>${esc(a.t)}</span><small>${esc(a.processId+' · Step '+a.n)}</small></div>`).join('')}</div>`:empty('No activity-level control field is populated in this source.')}</section><section class="tw-control-section"><h2>KPI definitions & targets</h2><p class="tw-note">Targets marked “Illustrative” are examples in the source; they are not measured performance results.</p>${c.kpis?.length?`<div class="tw-table-scroll" tabindex="0"><table class="tw-table"><thead><tr><th>KPI</th><th>Definition</th><th>Source target</th></tr></thead><tbody>${c.kpis.map(row=>`<tr>${row.map(v=>`<td>${esc(textValue(v))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('No standalone KPI target register is documented for this tower.')}${c.kpiNote?`<p class="tw-note">${esc(c.kpiNote)}</p>`:''}</section>`;}
function sourcePage(title,description,sections,options={}){const initial=options.ai?Math.max(0,sections.findIndex(s=>s.id.startsWith('opp-'))):0;return pageHeader(title,description)+`${options.ai?`<div class="tw-ai-notice">${icon('ai')}<div><strong>Proposals for review</strong><p>These are the source’s suggestions and potential future outcomes. Feasibility and LT comments are retained; As-Is KPI counts remain unchanged.</p></div></div>`:''}<div class="tw-source-tools">${sections.length>1?`<label class="tw-select tw-section-select"><span>Section</span><select id="tw-source-section">${sections.map((s,i)=>`<option value="${i}" ${i===initial?'selected':''}>${esc(titleClean(s.title))}</option>`).join('')}</select></label>`:''}${search('tw-source-search','Search the selected source section…')}<span class="tw-search-result" role="status">All source records</span></div><div id="tw-source-body">${sections.map((s,i)=>`<div data-source-index="${i}" ${i!==initial?'hidden':''}>${sourceBlock(s)}</div>`).join('')||empty('No additional information is documented.')}</div>`;}
function wireSource(){const change=()=>{const selected=$('#tw-source-section')?.value||'0';document.querySelectorAll('[data-source-index]').forEach(el=>el.hidden=el.dataset.sourceIndex!==selected);const root=$(`[data-source-index="${selected}"]`);$('#tw-source-search').value='';if(root){root.querySelectorAll('[hidden]:not(.tw-source-empty)').forEach(e=>e.hidden=false);const empty=root.querySelector('.tw-source-empty');if(empty)empty.hidden=true;searchableSource(root,$('#tw-source-search'))}$('.tw-search-result').textContent='All source records'};if($('#tw-source-section'))$('#tw-source-section').onchange=change;change();}
function goMap(mode,stage=null){const id=activeId;closeDashboard();openMap?.(id,stage,mode,document.body.classList.contains('keyboard-input'));}
async function render(next,focus=false){const ticket=++token,scenario=getScenario(activeId);view=next;destroyDashboard();$('#tw-scroll').scrollTop=0;document.querySelectorAll('[data-nav]').forEach(b=>{const active=b.dataset.nav===view;b.setAttribute('aria-current',active?'page':'false')});$('#tw-mobile-section').value=view;$('#tower-workbench').dataset.view=view;const page=$('#tw-page');page.innerHTML='<div class="tw-loading" role="status"><span></span>Loading the source registers…</div>';
 try{const [all,t]=await Promise.all([content(),getTower(activeId,scenario)]);if(ticket!==token||$('#tower-workbench').hidden)return;const original=all[t.sourceKey],isAI=scenario==='tobe',c=isAI?{...original,asIs:original.ai,controls:original.aiControls,kpis:original.aiKpis,kpiNote:original.aiKpiNote}:original;
 page.dataset.scenario=scenario;if(view==='handoffs')page.innerHTML=handoffs(t);else if(view==='overview')page.innerHTML=overview(t,c);else if(view==='activities')page.innerHTML=activities(t);else if(view==='tpis')page.innerHTML=tpis(t,c);else if(view==='controls')page.innerHTML=controls(t,c);else if(view==='pain')page.innerHTML=sourcePage('Pain points',isAI?'Source pain points and the proposed resolutions, including feasibility and review comments.':'The documented As Is pain points, kept in their source stage and process groups.',c.asIs.filter(s=>isAI?/Pain point resolution/i.test(s.title):s.id.startsWith('pp-')));else if(view==='ai')page.innerHTML=sourcePage('AI suggestions','Explore proposed changes, potential activity mixes, feasibility reviews and solution registers.',c.ai,{ai:true});else page.innerHTML=sourcePage('Source notes','Original tower context, source metrics, validation updates, regional variations and scope notes.',c.asIs.filter(s=>isAI?!/Pain point resolution/i.test(s.title):!s.id.startsWith('pp-')&&!s.id.startsWith('kp-')));
 decorateSources(page);if(view==='handoffs'){wireHandoffs(t);if(entryContext?.upstream){const d=KPI[activeId].dependencies.find(d=>d.id===entryContext.upstream);if(d)showDrawer(d.name,`<p class="tw-note">${d.count} documented inbound handoffs to ${esc(t.name)}.</p>${d.evidence.map(r=>`<h3>${esc(r.flow)}</h3><dl class="tw-fields">${field('Upstream party',r.party)}${field('What moves',r.detail)}${field('Source',r.source)}</dl>`).join('')}`);entryContext=null;}}if(view==='activities')wireActivities(t);if(view==='tpis')wireTpis(t);if(['pain','ai','notes'].includes(view))wireSource();page.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>goMap(b.dataset.map));page.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>goMap('detail',b.dataset.stage));page.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{activityType=b.dataset.activity;render('activities',true)});page.querySelectorAll('[data-chart-handoffs]').forEach(b=>b.onclick=()=>render('handoffs',true));page.querySelectorAll('[data-chart-flow]').forEach(b=>b.onclick=async()=>{const index=+b.dataset.chartFlow;await render('handoffs',true);neural?.selectFlow(index,true)});animateNumbers(page);if(focus)$('#tw-page-title').focus({preventScroll:true});
 }catch(e){if(ticket!==token)return;page.innerHTML=pageHeader('Source registers unavailable','The local content file could not be read.')+`<p>${esc(e.message)}</p>${button('Try again','id="tw-retry"',true)}`;$('#tw-retry').onclick=()=>render(view)}
}
export function openDashboard(id,next='handoffs',context=null){
 entryContext=context;
 cancelPageNavigation();
 const t=REAL[id];if(!t)return;const modal=$('#tower-workbench'),opening=modal.hidden;if(opening){opener=document.activeElement;$('#section-1').inert=true;$('#process-workspace').inert=true;document.body.classList.add('modal-open')}
 activeId=id;activityType={auto:'auto',semi:'hyb',manual:'man'}[next]||'';next=activityType?'activities':NAV.some(n=>n[0]===next)?next:'overview';destroyDashboard();modal.innerHTML=shell(t);modal.hidden=false;bindScenarioControl(modal,value=>{entryContext=null;activityType='';setScenario(id,value);render(view,false);});$('#tw-close').onclick=closeDashboard;$('#tw-drawer-close').onclick=closeDrawer;$('#tw-drawer-backdrop').onclick=closeDrawer;modal.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{entryContext=null;render(b.dataset.nav,true)});$('#tw-mobile-section').onchange=e=>{entryContext=null;render(e.target.value,true)};
 modal.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();if(!$('#tw-drawer').hidden){closeDrawer();return}if(fullscreenPlaceholder){setHandoffFullscreen(false);return}if(view==='handoffs'&&neural?.clearSelection())return;closeDashboard();return}if(e.key==='Tab'){const container=!$('#tw-drawer').hidden?$('#tw-drawer'):fullscreenPlaceholder?$('#tw-network-panel'):modal,els=[...container.querySelectorAll('button,a[href],input,select,summary,[tabindex="0"]')].filter(el=>!el.disabled&&el.tabIndex>=0&&el.getClientRects().length&&!el.closest('[hidden],[inert]'));const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};
 $('#tw-close').focus({preventScroll:true});render(next);if(opening&&motion())modal.animate([{opacity:.65,transform:'translateY(10px)'},{opacity:1,transform:'none'}],{duration:240,easing:'cubic-bezier(.23,1,.32,1)'});
}
export function closeDashboard(){token++;destroyDashboard();$('#tower-workbench').hidden=true;$('#section-1').inert=false;$('#process-workspace').inert=false;document.body.classList.remove('modal-open');opener?.focus({preventScroll:true})}
